using System;
using System.IO;
using System.Collections.Generic;
using System.Web.Script.Serialization;
using LmuQuadViewLauncher;
class LaunchServiceTests {
    static void Check(bool yes,string message) { if(!yes) throw new Exception(message); }
    static void Reject(Action action,string message) { bool rejected=false;try { action(); } catch { rejected=true; } Check(rejected,message); }
    static int Main() {
        var root=Path.Combine(Path.GetTempPath(),"lmu-launch-tests-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
        var originalOffset=Environment.GetEnvironmentVariable("LMU_QV_FOCUS_OFFSET_X_PERCENT");
        var originalVrs=Environment.GetEnvironmentVariable("LMU_QV_VRS_EXCLUSIVE");
        var originalCrop=Environment.GetEnvironmentVariable("LMU_QV_CROP_WIDTH_PERCENT");
        var originalCulture=System.Threading.Thread.CurrentThread.CurrentCulture;
        try {
            System.Threading.Thread.CurrentThread.CurrentCulture=System.Globalization.CultureInfo.GetCultureInfo("de-DE");
            var providerRoot=Path.Combine(root,"provider's files");Directory.CreateDirectory(providerRoot);
            var dll=Path.Combine(providerRoot,"provider.dll");File.WriteAllBytes(dll,new byte[]{1,2,3});
            var manifest=Path.Combine(providerRoot,"quad.json");
            var original="{\"file_format_version\":\"1.0.0\",\"api_layer\":{\"name\":\"XR_APILAYER_MBUCCHIA_quad_views_foveated\",\"library_path\":\"provider.dll\",\"api_version\":\"1.0\",\"disable_environment\":\"DISABLE_XR_APILAYER_MBUCCHIA_quad_views_foveated\",\"enable_environment\":\"ENABLE_TEST\"}}";
            File.WriteAllText(manifest,original);
            var provider=LaunchService.ReadProviderManifest(manifest);
            Check(provider.Library==dll,"Provider DLL moved from original folder");
            var plan=LaunchService.MakeLayerPlan(root,"QVFR",provider,Path.Combine(root,"run"));
            Check(plan.Layers=="XR_APILAYER_LMU_quadview;XR_APILAYER_MBUCCHIA_quad_views_foveated","Windows layer ordering");
            var json=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(File.ReadAllText(plan.ExplicitManifest));
            var layer=(Dictionary<string,object>)json["api_layer"];
            Check(!layer.ContainsKey("disable_environment")&&!layer.ContainsKey("enable_environment"),"Explicit activation switches retained");
            Check((string)layer["library_path"]==dll,"Explicit DLL path changed");
            Check(File.ReadAllText(manifest)==original,"Installed manifest modified");
            var settings=new LauncherSettings {GameDirectory=Path.Combine(root,"game's folder"),Backend="QVFR",FoveationMode="fixed",DebugFocus=true,NativeOuterResolution=false,OuterBlur=1.25m};
            Environment.SetEnvironmentVariable("LMU_QV_VRS_EXCLUSIVE","1");
            Environment.SetEnvironmentVariable("LMU_QV_FOCUS_OFFSET_X_PERCENT","49");
            Environment.SetEnvironmentVariable("LMU_QV_CROP_WIDTH_PERCENT","29");
            settings.CropWidthPercent=75.5m;settings.CropHeightPercent=42.25m;
            settings.FocusOffsetXPercent=-12.5m;settings.FocusOffsetYPercent=50;
            var info=LaunchService.MakeStartInfo(root,settings,plan,Path.Combine(root,"quad.log"));
            Check(info.EnvironmentVariables["LMU_QV_CROP_WIDTH_PERCENT"]=="75.5"&&info.EnvironmentVariables["LMU_QV_CROP_HEIGHT_PERCENT"]=="42.25","Independent crop not exported invariantly");
            Check(Environment.GetEnvironmentVariable("LMU_QV_CROP_WIDTH_PERCENT")=="29","Crop leaked into host environment");
            Check(info.EnvironmentVariables["LMU_QV_FOCUS_OFFSET_X_PERCENT"]=="-12.5"&&info.EnvironmentVariables["LMU_QV_FOCUS_OFFSET_Y_PERCENT"]=="50","Signed offsets not exported invariantly");
            Check(Environment.GetEnvironmentVariable("LMU_QV_FOCUS_OFFSET_X_PERCENT")=="49","Offset leaked into host environment");
            var metadataFactory=typeof(LaunchService).GetMethod("PreparedMetadata",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic);
            Check(metadataFactory!=null,"Prepared metadata must be inspectable without starting LMU");
            Directory.CreateDirectory(Path.Combine(root,"build"));File.WriteAllBytes(Path.Combine(root,"build","lmu_quadview.dll"),new byte[]{4,5,6});
            var prepared=metadataFactory.Invoke(null,new object[]{root,settings,plan,info,Path.Combine(root,"quad.log")});
            var savedMetadata=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(new JavaScriptSerializer().Serialize(prepared));
            Check(Convert.ToDecimal(savedMetadata["CropWidthPercent"])==75.5m&&Convert.ToDecimal(savedMetadata["CropHeightPercent"])==42.25m,"Crop missing from run metadata");
            Check(Convert.ToDecimal(savedMetadata["FocusOffsetXPercent"])==-12.5m&&Convert.ToDecimal(savedMetadata["FocusOffsetYPercent"])==50,"Offsets missing from run metadata");
            Check(!info.UseShellExecute&&info.Arguments=="+XR"&&info.FileName==Path.Combine(settings.GameDirectory,"Le Mans Ultimate.exe"),"Must launch executable directly");
            Check(info.EnvironmentVariables[plan.DisableVariable]=="1","Implicit QVFR not disabled in child");
            Check(Environment.GetEnvironmentVariable(plan.DisableVariable)==null,"Host process environment modified");
            Check(info.EnvironmentVariables["LMU_QV_FOVEATION_MODE"]=="fixed"&&info.EnvironmentVariables["LMU_QV_DEBUG_FOCUS"]=="1","Mode/outline lost");
            Check(info.EnvironmentVariables["LMU_QV_OUTER_BLUR"]=="1.25","Blur control not passed as invariant decimal");
            Check(info.EnvironmentVariables["LMU_QV_NATIVE_OUTER"]=="0"&&info.EnvironmentVariables["LMU_QV_VRS_EXCLUSIVE"]=="0","Inherited experimental controls leak");
            Check(info.EnvironmentVariables["LMU_QV_VECTORXR_DIRECT_INPUTS"]=="0","QVFR must retain its original input flags");
            Check(info.EnvironmentVariables["LMU_QV_USE_RUNTIME_SETTINGS"]=="1"&&info.EnvironmentVariables["LMU_QV_FOCUS_PIXELS_PERCENT"]=="100","Provider dimensions scaled twice");
            var native=LaunchService.MakeLayerPlan(root,"Native",provider,null);
            var fullView=LaunchService.MakeStartInfo(root,new LauncherSettings(),native,Path.Combine(root,"zero.log"));
            Check(fullView.EnvironmentVariables["LMU_QV_CROP_WIDTH_PERCENT"]=="100"&&fullView.EnvironmentVariables["LMU_QV_CROP_HEIGHT_PERCENT"]=="100","Stale inherited crop survived defaults");
            Check(LaunchService.MakeStartInfo(root,new LauncherSettings(),native,Path.Combine(root,"zero.log")).EnvironmentVariables["LMU_QV_FOCUS_OFFSET_X_PERCENT"]=="0","Stale inherited offset survived defaults");
            Check(native.Layers=="XR_APILAYER_LMU_quadview"&&native.DisableVariable==provider.DisableVariable,"Native did not suppress implicit emulation");
            var vectorManifest=Path.Combine(providerRoot,"vector.json");
            var vectorOriginal=original.Replace("XR_APILAYER_MBUCCHIA_quad_views_foveated","XR_APILAYER_DIENERTECH_VECTORXR");
            vectorOriginal=vectorOriginal.Replace("\"api_version\":\"1.0\"","\"api_version\":\"1.1\",\"instance_extensions\":[{\"name\":\"XR_VARJO_quad_views\",\"extension_version\":\"2\"},{\"name\":\"XR_VARJO_foveated_rendering\",\"extension_version\":\"3\"}]");
            File.WriteAllText(vectorManifest,vectorOriginal);
            var vector=LaunchService.ReadProviderManifest(vectorManifest,true,"VectorXR");
            Check(vector.Name==LaunchService.VectorXrProviderName&&vector.Library==dll,"VectorXR identity/library resolution");
            Check(LaunchService.FindProviderInCandidates(new[]{manifest,vectorManifest},"VectorXR")==vectorManifest,"VectorXR discovery chose QVFR");
            Check(LaunchService.FindProviderInCandidates(new[]{vectorManifest,manifest},"QVFR")==manifest,"QVFR discovery chose VectorXR");
            Reject(delegate{LaunchService.ReadProviderManifest(manifest,true,"VectorXR");},"VectorXR accepted mbucchia manifest");
            Reject(delegate{LaunchService.ReadProviderManifest(vectorManifest);},"QVFR accepted VectorXR manifest");
            Reject(delegate{LaunchService.MakeLayerPlan(root,"VectorXR",provider,Path.Combine(root,"wrong-vector"));},"Provider/backend mismatch accepted");
            var vectorPlan=LaunchService.MakeLayerPlan(root,"VectorXR",vector,Path.Combine(root,"vector-run"));
            Check(vectorPlan.Layers=="XR_APILAYER_LMU_quadview;XR_APILAYER_DIENERTECH_VECTORXR","VectorXR explicit order");
            Check(File.ReadAllText(vectorManifest)==vectorOriginal,"Installed VectorXR manifest changed");
            var vectorJson=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(File.ReadAllText(vectorPlan.ExplicitManifest));
            var vectorLayer=(Dictionary<string,object>)vectorJson["api_layer"];
            Check(!vectorLayer.ContainsKey("disable_environment")&&!vectorLayer.ContainsKey("enable_environment"),"Explicit VectorXR activation switches retained");
            Check((string)vectorLayer["library_path"]==dll,"VectorXR DLL location changed");
            Check(((System.Collections.ICollection)vectorLayer["instance_extensions"]).Count==2&&(string)vectorLayer["api_version"]=="1.1","VectorXR extension declarations/API version lost");
            var toolkit=Path.Combine(providerRoot,"toolkit.json");
            File.WriteAllText(toolkit,original.Replace("XR_APILAYER_MBUCCHIA_quad_views_foveated","XR_APILAYER_MBUCCHIA_toolkit"));
            var customQvfr=Path.Combine(providerRoot,"custom-quad.json");
            File.WriteAllText(customQvfr,original.Replace("DISABLE_XR_APILAYER_MBUCCHIA_quad_views_foveated","DISABLE_VENDOR_QUAD_EMULATION"));
            var malformedManifest=Path.Combine(providerRoot,"unrelated-broken.json");
            File.WriteAllText(malformedManifest,"{ not valid JSON");
            foreach(var backend in new[]{"Native","QVFR","VectorXR"}) {
                var scanPlan=new LaunchService.LayerPlan();
                LaunchService.AddImplicitDisables(scanPlan,new[]{malformedManifest,customQvfr},backend);
                Check(scanPlan.DisableVariables.Contains("DISABLE_VENDOR_QUAD_EMULATION"),"Malformed unrelated manifest blocked isolation for "+backend);
            }
            Reject(delegate{LaunchService.ReadProviderManifest(malformedManifest);},"Explicit malformed provider must still be rejected");
            LaunchService.AddImplicitDisables(vectorPlan,new[]{manifest,vectorManifest,toolkit,customQvfr},"VectorXR");
            foreach(var providerName in new[]{"Native","QVFR","VectorXR"})foreach(var foveation in new[]{"fixed","auto"}) {
                var position=new LauncherSettings {Backend=providerName,FoveationMode=foveation,FocusOffsetXPercent=50,FocusOffsetYPercent=-50,CropWidthPercent=25,CropHeightPercent=80.5m};
                var selectedPlan=providerName=="Native"?native:providerName=="QVFR"?plan:vectorPlan;
                var child=LaunchService.MakeStartInfo(root,position,selectedPlan,Path.Combine(root,"position.log"));
                Check(child.EnvironmentVariables["LMU_QV_CROP_WIDTH_PERCENT"]=="25"&&child.EnvironmentVariables["LMU_QV_CROP_HEIGHT_PERCENT"]=="80.5","Crop lost for "+providerName+" "+foveation);
                Check(child.EnvironmentVariables["LMU_QV_FOCUS_OFFSET_X_PERCENT"]=="50"&&child.EnvironmentVariables["LMU_QV_FOCUS_OFFSET_Y_PERCENT"]=="-50","Offsets lost for "+providerName+" "+foveation);
            }
            var vectorSettings=new LauncherSettings {GameDirectory=settings.GameDirectory,Backend="VectorXR",FoveationMode="fixed"};
            var vectorInfo=LaunchService.MakeStartInfo(root,vectorSettings,vectorPlan,Path.Combine(root,"vector.log"));
            Check(vectorInfo.EnvironmentVariables["LMU_QV_VECTORXR_DIRECT_INPUTS"]=="1","VectorXR direct-input request missing");
            var nativeInfo=LaunchService.MakeStartInfo(root,new LauncherSettings{GameDirectory=settings.GameDirectory,Backend="Native"},native,Path.Combine(root,"native.log"));
            Check(nativeInfo.EnvironmentVariables["LMU_QV_VECTORXR_DIRECT_INPUTS"]=="0","Native must retain its original input flags");
            Check(vectorInfo.EnvironmentVariables["LMU_QV_PROFILE"]=="0","Profiling must be disabled by default");
            Check(vectorInfo.EnvironmentVariables["LMU_QV_STEREO_AUDIT"]=="0"&&vectorInfo.EnvironmentVariables["LMU_QV_STEREO_AUDIT_DIR"]=="","Draw audit must default off");
            Check(vectorInfo.EnvironmentVariables["LMU_QV_STEREO_SHADER_CAPTURE"]=="0","Shader export must default off");
            Check(vectorInfo.EnvironmentVariables["LMU_QV_STEREO_DRAW_PROOF"]=="0"&&vectorInfo.EnvironmentVariables["LMU_QV_CPU_UPLOAD_REUSE"]=="0","Prototypes must default off");
            Check(vectorInfo.EnvironmentVariables["LMU_QV_PROFILE_SECONDS"]=="120","Capture duration default missing");
            vectorSettings.RenderProfiling=true;
            vectorSettings.StereoDrawAudit=true;
            vectorSettings.StereoShaderCapture=true;
            vectorSettings.StereoPairProof=true;vectorSettings.CpuUploadReuse=true;
            vectorSettings.RenderProfileSeconds=300;
            var profiled=LaunchService.MakeStartInfo(root,vectorSettings,vectorPlan,Path.Combine(root,"profile.log"));
            Check(profiled.EnvironmentVariables["LMU_QV_PROFILE"]=="1","Profiling not enabled in child");
            Check(profiled.EnvironmentVariables["LMU_QV_PROFILE_SECONDS"]=="300","Selected capture length not passed to child");
            Check(profiled.EnvironmentVariables["LMU_QV_STEREO_AUDIT"]=="1"&&profiled.EnvironmentVariables["LMU_QV_STEREO_AUDIT_DIR"]==root,"Audit enable/output directory not passed to child");
            Check(profiled.EnvironmentVariables["LMU_QV_STEREO_SHADER_CAPTURE"]=="1","Shader export not passed to child");
            Check(profiled.EnvironmentVariables["LMU_QV_STEREO_DRAW_PROOF"]=="1"&&profiled.EnvironmentVariables["LMU_QV_CPU_UPLOAD_REUSE"]=="1","Prototype options not passed to child");
            vectorSettings.StereoDrawAudit=false;
            Check(LaunchService.MakeStartInfo(root,vectorSettings,vectorPlan,Path.Combine(root,"audit-off.log")).EnvironmentVariables["LMU_QV_STEREO_SHADER_CAPTURE"]=="0","Audit-off must override shader export");
            Check(LaunchService.MakeStartInfo(root,vectorSettings,vectorPlan,Path.Combine(root,"proof-off.log")).EnvironmentVariables["LMU_QV_STEREO_DRAW_PROOF"]=="0","Audit-off must override paired proof");
            vectorSettings.StereoDrawAudit=true;
            vectorSettings.DiagnosticsEnabled=false;
            var quiet=LaunchService.MakeStartInfo(root,vectorSettings,vectorPlan,Path.Combine(root,"quiet.log"));
            Check(quiet.EnvironmentVariables["LMU_QV_DIAGNOSTICS"]=="0"&&quiet.EnvironmentVariables["LMU_QV_LOG"]=="","Diagnostics-off must suppress log path");
            Check(quiet.EnvironmentVariables["LMU_QV_PROFILE"]=="0","Diagnostics-off must override saved profiling-on");
            Check(quiet.EnvironmentVariables["LMU_QV_STEREO_AUDIT"]=="0"&&quiet.EnvironmentVariables["LMU_QV_STEREO_AUDIT_DIR"]=="","Master diagnostics-off must override audit-on");
            Check(quiet.EnvironmentVariables["LMU_QV_STEREO_SHADER_CAPTURE"]=="0","Master diagnostics-off must override shader export");
            Check(quiet.EnvironmentVariables["LMU_QV_STEREO_DRAW_PROOF"]=="0"&&quiet.EnvironmentVariables["LMU_QV_CPU_UPLOAD_REUSE"]=="1","Master switch must disable proof while preserving the rendering option");
            Check(quiet.EnvironmentVariables["XR_ENABLE_API_LAYERS"]==profiled.EnvironmentVariables["XR_ENABLE_API_LAYERS"],"Diagnostics changed renderer layer chain");
            vectorSettings.DiagnosticsEnabled=true;
            vectorSettings.CpuUploadBatch=true;
            var fast=LaunchService.MakeStartInfo(root,vectorSettings,vectorPlan,Path.Combine(root,"fast.log"));
            Check(fast.EnvironmentVariables["LMU_QV_CPU_UPLOAD_BATCH"]=="1"&&fast.EnvironmentVariables["LMU_QV_CPU_UPLOAD_REUSE"]=="0","Combined upload mode must own its reuse path");
            Check(fast.EnvironmentVariables["LMU_QV_STEREO_AUDIT"]=="0"&&fast.EnvironmentVariables["LMU_QV_STEREO_DRAW_PROOF"]=="0"&&fast.EnvironmentVariables["LMU_QV_STEREO_SHADER_CAPTURE"]=="0","Draw audit does not understand ranged CB bindings and must stay off during batching");
            Check(fast.EnvironmentVariables["LMU_QV_PROFILE"]=="1","Ordinary profiling must remain available with CPU fast path");
            vectorSettings.DiagnosticsEnabled=false;
            Check(LaunchService.MakeStartInfo(root,vectorSettings,vectorPlan,Path.Combine(root,"quiet-fast.log")).EnvironmentVariables["LMU_QV_CPU_UPLOAD_BATCH"]=="1","CPU fast path must work with diagnostics off");
            vectorSettings.DiagnosticsEnabled=true;vectorSettings.CpuUploadBatch=false;
            Check(Environment.GetEnvironmentVariable("LMU_QV_PROFILE")==null,"Profiling switch leaked into host");
            Check(vectorInfo.EnvironmentVariables["XR_ENABLE_API_LAYERS"]==vectorPlan.Layers,"VectorXR child layer list");
            foreach(var variable in new[]{"DISABLE_XR_APILAYER_DIENERTECH_VECTORXR","DISABLE_XR_APILAYER_MBUCCHIA_quad_views_foveated","DISABLE_QUAD_VIEWS_FOVEATED","DISABLE_VENDOR_QUAD_EMULATION","DISABLE_XR_APILAYER_MBUCCHIA_toolkit"})
                Check(vectorInfo.EnvironmentVariables[variable]=="1","Conflicting/duplicate implicit layer not suppressed: "+variable);
            Check(Environment.GetEnvironmentVariable("DISABLE_XR_APILAYER_DIENERTECH_VECTORXR")==null,"VectorXR suppression leaked into host");
            Check(Environment.GetEnvironmentVariable("DISABLE_XR_APILAYER_MBUCCHIA_toolkit")==null,"Toolkit suppression leaked into host");
            Check(vectorInfo.EnvironmentVariables["LMU_QV_FOVEATION_MODE"]=="fixed"&&vectorInfo.EnvironmentVariables["LMU_QV_USE_RUNTIME_SETTINGS"]=="1","VectorXR fixed/runtime sizing controls lost");
            Reject(delegate{LaunchService.MakeLayerPlan(root,"VectorXR",vector,Path.Combine(root,"vector-run"));},"VectorXR run directory overwritten");
            File.WriteAllText(vectorManifest,vectorOriginal.Replace("DISABLE_XR_APILAYER_DIENERTECH_VECTORXR","UNRELATED_SWITCH"));
            Reject(delegate{LaunchService.ReadProviderManifest(vectorManifest,true,"VectorXR");},"Unsafe VectorXR activation switch accepted");
            Reject(delegate{LaunchService.AddImplicitDisables(vectorPlan,new[]{vectorManifest},"VectorXR");},"Unsafe installed provider suppression ignored");
            File.WriteAllText(vectorManifest,vectorOriginal);
            Reject(delegate{LaunchService.MakeLayerPlan(root+";bad","Native",null,null);},"Search separator allowed in root");
            Reject(delegate{LaunchService.MakeLayerPlan(root,"QVFR",provider,Path.Combine(root,"run"));},"Existing manifest directory overwritten");
            File.Delete(dll);Reject(delegate{LaunchService.ReadProviderManifest(manifest);},"Missing provider DLL accepted");
            File.WriteAllBytes(dll,new byte[]{1,2,3});File.WriteAllText(manifest,original.Replace("XR_APILAYER_MBUCCHIA_quad_views_foveated","wrong_layer"));
            Reject(delegate{LaunchService.ReadProviderManifest(manifest);},"Unrelated layer accepted");
            var fakeExe=Path.Combine(root,"fake.exe");File.WriteAllText(fakeExe,"not LMU");
            Reject(delegate{LaunchService.ValidateExecutable(fakeExe);},"Pinned game hash guard weakened");
            Reject(delegate{LaunchService.Prepare(root,settings);},"Prepare accepted missing game/package");
            Console.WriteLine("LaunchService tests passed: QVFR/VectorXR/native, discovery, explicit order, duplicate/conflicting-layer isolation, manifests, environment reset, pinned hash guard");
            return 0;
        } finally {
            System.Threading.Thread.CurrentThread.CurrentCulture=originalCulture;
            Environment.SetEnvironmentVariable("LMU_QV_CROP_WIDTH_PERCENT",originalCrop);
            Environment.SetEnvironmentVariable("LMU_QV_FOCUS_OFFSET_X_PERCENT",originalOffset);
            Environment.SetEnvironmentVariable("LMU_QV_VRS_EXCLUSIVE",originalVrs);
            if(Path.GetFullPath(root).StartsWith(Path.GetFullPath(Path.GetTempPath()),StringComparison.OrdinalIgnoreCase)) Directory.Delete(root,true);
        }
    }
}
